import {SOUND_TONE_MODEL,createSoundWindowPlayer} from './sound-window-audio.mjs';
// Four nominal sine settings. No notebook reads, initialization or writes.
export const SOUND_WINDOW=Object.freeze({seconds:1/110,intervals:32,samples:257,drawLimit:2.4});
export const freshSoundWindow=()=>({pitch:'low',size:1,held:null,marker:false,tick:0});
export const validSoundSetting=s=>s!==null&&typeof s==='object'&&!Array.isArray(s)&&['low','high'].includes(s.pitch)&&[1,2].includes(s.size);
export const validSoundWindow=s=>validSoundSetting(s)&&(s.held===null||validSoundSetting(s.held))&&typeof s.marker==='boolean'&&Number.isInteger(s.tick)&&s.tick>=0&&s.tick<=SOUND_WINDOW.intervals;
export function soundTonePlan(s){return validSoundSetting(s)?{frequency:SOUND_TONE_MODEL.frequencies[s.pitch==='low'?0:1],gain:SOUND_TONE_MODEL.gains[s.size-1]}:null;}
export function soundWindowWave(s){const plan=soundTonePlan(s);if(!plan)return null;return {frequency:plan.frequency,amplitude:s.size,cycles:plan.frequency*SOUND_WINDOW.seconds,window:SOUND_WINDOW.seconds,points:Array.from({length:SOUND_WINDOW.samples},(_,i)=>{const time=i/(SOUND_WINDOW.samples-1)*SOUND_WINDOW.seconds;return {time,value:s.size*Math.sin(2*Math.PI*plan.frequency*time)};})};}
export function soundWindowValue(s,tick){const plan=soundTonePlan(s);return plan&&Number.isInteger(tick)&&tick>=0&&tick<=SOUND_WINDOW.intervals?s.size*Math.sin(2*Math.PI*plan.frequency*tick/(SOUND_WINDOW.intervals*110)):null;}
export function formatSoundValue(value,spoken=false){if(!Number.isFinite(value))return '';const rounded=Math.round(value*100)/100;if(rounded===0)return '0';const text=Math.abs(rounded).toFixed(2).replace(/\.?0+$/,'');return (rounded<0?(spoken?'minus ':'−'):'')+text;}
export function compareSoundWindow(s){if(!validSoundWindow(s))return null;if(!s.held)return 'Hold one setting, then change a control to compare.';const f=s.pitch!==s.held.pitch,a=s.size!==s.held.size;return f&&a?'Both frequency and signal size changed.':f?'The frequency changed; signal size stayed the same.':a?'Signal size changed; frequency stayed the same.':'Same frequency and signal size.';}
export function changeSoundWindow(s,action,value){
 if(!validSoundWindow(s))return null;if(action==='reset')return freshSoundWindow();const next={...s,held:s.held?{pitch:s.held.pitch,size:s.held.size}:null};
 if(action==='pitch'&&['low','high'].includes(value))next.pitch=value;
 else if(action==='size'&&[1,2].includes(value))next.size=value;
 else if(action==='hold')next.held={pitch:s.pitch,size:s.size};
 else if(action==='clear')next.held=null;
 else if(action==='marker'&&typeof value==='boolean')next.marker=value;
 else if(action==='tick'&&[-1,1].includes(value))next.tick=Math.max(0,Math.min(SOUND_WINDOW.intervals,s.tick+value));
 else return null;return next;
}

export const soundCaptions=Object.freeze([{"start": 0.2, "end": 2.4, "text": "A ruler, held down on a table. Slowed right down."}, {"start": 2.4, "end": 5.2, "text": "Let go: the free end swings back and forth. It vibrates."}, {"start": 5.2, "end": 8.0, "text": "The pen draws each swing as it happens."}, {"start": 8.2, "end": 10.0, "text": "Push the end down further before you let go."}, {"start": 10.0, "end": 13.0, "text": "A bigger swing makes a louder sound."}, {"start": 13.0, "end": 16.0, "text": "It swings just as fast as before, so the note stays the same."}, {"start": 16.2, "end": 18.4, "text": "Slide the ruler in, so less of it hangs over the edge."}, {"start": 18.4, "end": 20.8, "text": "A shorter free end vibrates faster."}, {"start": 20.8, "end": 24.0, "text": "Faster vibration makes a higher note."}, {"start": 24.2, "end": 26.4, "text": "Bang a metal tray near a drum with rice on it."}, {"start": 26.4, "end": 29.0, "text": "The air passes the vibration along, bunching and spreading."}, {"start": 29.0, "end": 32.0, "text": "Air makes the drum skin vibrate, so the rice jumps."}, {"start": 32.2, "end": 36.0, "text": "Something vibrates. The vibration is passed on. That is sound."}].map(Object.freeze));

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,attrs='')=>`<button type="button" data-sound-action="${action}" ${attrs}>${esc(label)}</button>`;
let visit=null,soundFilmCleanup=null,soundFilmPause=null,player=null;
export function pauseSoundFilm(){soundFilmPause?.();}
export function stopSoundFilm(){soundFilmCleanup?.();soundFilmCleanup=null;soundFilmPause=null;}
export function stopSoundTone(reason='stopped'){return player?.stop(reason);}
export function resetSoundWindow(){stopSoundFilm();stopSoundTone('reset');visit=null;}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,model:freshSoundWindow(),film:false,details:{},status:''};return visit;}
export function soundWindowDrawing(s,label='Current',marker=false,tick=0){
 const w=soundWindowWave(s);if(!w)return '';const x=t=>50+t/SOUND_WINDOW.seconds*400,y=v=>120-v*40;
 const path=w.points.map((p,i)=>`${i?'L':'M'}${x(p.time).toFixed(3)} ${y(p.value).toFixed(3)}`).join('');
 const title=`${label} computer signal: ${w.frequency} hertz, relative amplitude ${s.size}, ${w.cycles} complete cycles in the same time window.`,id=label.toLowerCase();
 return `<svg data-sound-drawing="${id}" viewBox="0 0 480 270" role="img" aria-labelledby="sound-${id}-title sound-${id}-desc"><title id="sound-${id}-title">${esc(title)}</title><desc id="sound-${id}-desc">Steady part of a sine signal over one second divided by one hundred and ten. Fixed labelled signal ticks minus two, zero and plus two, with drawing headroom beyond them. This is not air moving up and down.</desc><g class="sw-axes"><path d="M50 24V216M50 120H450"/>${[-2,0,2].map(v=>`<path d="M46 ${y(v)}H450" class="sw-grid"/><text x="39" y="${y(v)+5}" text-anchor="end">${v===2?'+2':v===-2?'−2':'0'}</text>`).join('')}<text x="50" y="238">0</text><text x="450" y="238" text-anchor="end">1/110 s</text><text x="250" y="262" text-anchor="middle">time</text><text x="50" y="17">relative signal</text></g><path class="sw-wave" data-sound-wave d="${path}"/>${marker?`<g class="sw-marker"><path d="M${50+tick/32*400} 24V216"/><circle cx="${50+tick/32*400}" cy="${y(soundWindowValue(s,tick))}" r="5"/></g>`:''}</svg>`;
}
function figure(s,label,model){const w=soundWindowWave(s),value=soundWindowValue(s,model.tick);return `<figure class="sw-picture" data-sound-figure="${label.toLowerCase()}"><figcaption><h2>${label} setting</h2><span>${w.frequency} Hz · relative signal size ${s.size}</span><span>${w.cycles===2?'Two':'Four'} cycles · same short time window</span></figcaption>${soundWindowDrawing(s,label,model.marker,model.tick)}${model.marker?`<p data-sound-marker-value="${label.toLowerCase()}" aria-label="${label} setting at time marker ${model.tick} of 32 intervals: calculated signal ${formatSoundValue(value,true)} relative units.">${label} setting at time marker ${model.tick} of 32 intervals: calculated signal <strong>${formatSoundValue(value)}</strong> relative units.</p>`:''}</figure>`;}
const framing='This silent film shows a slowed, exaggerated model. The pen follows the ruler tip; its newest mark is at the right-hand dot. The graph and ending squiggle are not air moving up and down. The tray vibrates and passes changes through the air to the drum. Our computer-tone numbers do not measure that ruler or drum.';
function moviePage(){return `<section class="sw-movie" data-sound-movie><h2>A vibration up close</h2><p>${framing}</p><video controls playsinline muted preload="none" poster="./assets/sound-wave-corrected.jpg" aria-label="A vibration up close, silent corrected film" aria-describedby="sound-current-caption"></video><p class="sw-caption" id="sound-current-caption" data-sound-caption>Read the complete transcript below at any time.</p><div class="sw-tools">${button('play','Play','disabled')}${button('replay','Replay','disabled')}${button('retry','Retry loading')}${button('return','Return to the Sound Window')}</div><p data-sound-load-status role="status"></p><details data-sound-transcript><summary>Read the complete film transcript</summary><ol>${soundCaptions.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol><p>Corrected derivative of the original <em>After the Storm</em> film made with Claude Motion; rendered Andika lettering, SIL Open Font License 1.1. No runtime player or font files are included.</p></details><p>The shorter part is the free overhang, not a cut ruler. Compare louder/softer with the same source and setup. The first ruler can also make sound; extra sound arcs are an illustration in the bigger-swing example. No real equipment is needed.</p></section>`;}
export function soundWindowPage(book,owner){
 const v=current(book,owner),s=v.model;
 const facts=(a,name)=>`<tr><th>${name}</th><td>${soundTonePlan(a).frequency} Hz</td><td>${a.size}</td><td>${soundWindowWave(a).cycles}</td></tr>`;
 return `<link rel="stylesheet" href="./sound-window.css"><section class="sw-room" data-sound-root><header><a href="#studio/bells">← Back to the Bell Studio</a><p class="eyebrow">Pip’s gathering call · sound and signals</p><h1 id="sound-title" tabindex="-1">The Sound Window</h1>${v.film?'':'<p>Can you change its pitch without changing the signal size? Every picture can be explored without sound.</p>'}</header>${v.film?moviePage():`<div class="sw-workbench"><section class="sw-console" aria-label="Change the computer signal"><div role="group" aria-label="Pitch">${['low','high'].map(k=>button(k,k==='low'?'Lower pitch':'Higher pitch',`aria-pressed="${s.pitch===k}"`)).join('')}</div><div role="group" aria-label="Signal size">${[1,2].map(k=>button('size'+k,k===1?'Smaller signal':'Bigger signal',`aria-pressed="${s.size===k}"`)).join('')}</div><div class="sw-tools">${button('hold',s.held?'Replace held setting':'Hold this setting')}${s.held?button('clear','Clear held setting'):''}</div><p data-sound-comparison>${compareSoundWindow(s)}</p><div class="sw-tools">${button('current','Play current sound')}${s.held?button('held','Play held sound'):''}${button('stop','Stop sound')}</div><p data-sound-status role="status">${esc(v.status||'Sound starts only when you ask.')}</p><p>Simple computer tones. Start with device volume low. Stop whenever you want.</p></section><div class="sw-pictures ${s.held?'sw-pair':''}">${figure(s,'Current',s)}${s.held?figure(s.held,'Held',s):''}</div></div><div class="sw-tools">${button('marker',s.marker?'Hide time marker':'Show time marker',`aria-pressed="${s.marker}"`)}${s.marker?button('earlier','Earlier sample',s.tick===0?'disabled':'')+button('later','Later sample',s.tick===32?'disabled':''):''}${button('reset','Start again')}</div><p>Relative signal, not measured sound level. Both pictures use the same scales.</p><div class="sw-invitation">${button('watch','Watch the vibration film')}<span>Optional silent film · 36 seconds</span></div><details data-sound-details="picture" ${v.details.picture?'open':''}><summary>About the picture and numbers</summary><p>This curve shows the steady part of a computer signal changing over time. It is not a recording of a ruler, a pressure measurement or the path of an air particle. Faster repetition makes a higher simple tone. Bigger signal size does not add cycles. More cycles does not make the signal taller. Signal size means amplitude: how far the curve reaches from the middle line. With the same pitch and listening setup, a bigger signal makes a louder tone.</p><table><caption>Same window, same scale</caption><thead><tr><th>Setting</th><th>Frequency</th><th>Relative amplitude</th><th>Cycles in this window</th></tr></thead><tbody>${facts(s,'Current')}${s.held?facts(s.held,'Held'):''}</tbody></table><p>Hertz means repetitions each second. This window is 1/110 second, about 9.09 milliseconds. The short playback lasts 0.6 second including a gentle start and finish; the plot shows only its steady repeating shape.</p><p>The optional marker compares one shared instant in both figures. It is not a tracked molecule. Values are calculated, not instrument readings.</p></details><details data-sound-details="listening" ${v.details.listening?'open':''}><summary>About listening</summary><p>These are simple computer tones, not recordings of a bell, ruler or drum. To compare loudness, keep pitch and your listening setup the same. Equal signal amplitudes at different pitches may not sound equally loud. Your speaker, volume setting and surroundings affect what you hear. No sound-level or hearing result is measured here.</p></details><details data-sound-details="grownups" ${v.details.grownups?'open':''}><summary>Grown-ups: exploring together</summary><p>Hold a setting. Change just one control. What changed in the picture? What stayed the same? This conversation is not recorded or scored.</p><p>Supplied teaching and nominal computer signals, not an independent skill, hearing observation, calibrated acoustic test or completed science strand. Settings stay local to this visit. Missing records never prove an example was unfamiliar. Bell Studio calls remain separate.</p></details>`}</section>`;
}
export function bindSoundWindow(book,{explorerId,notebook,isActive,render,beforeTone,beforeMovie,stopSound,stopSpeech}){
 const root=document.querySelector('[data-sound-root]');if(!root)return;const v=current(book,explorerId()),live=()=>visit===v&&root.isConnected&&notebook()===book&&explorerId()===v.owner&&isActive(),active=()=>live()&&!document.hidden;
 const redraw=action=>{render();document.querySelector(`[data-sound-action="${action}"]`)?.focus({preventScroll:true});};
 root.querySelectorAll('[data-sound-details]').forEach(d=>d.addEventListener('toggle',()=>{if(live())v.details[d.dataset.soundDetails]=d.open;}));
 root.querySelectorAll('[data-sound-action]').forEach(b=>b.addEventListener('click',()=>{
  if(!live()||b.disabled)return;const a=b.dataset.soundAction;if(v.film&&a!=='return')return;
  if(['current','held'].includes(a)){
   if(!active())return;const setting=a==='held'?v.model.held:v.model;if(!setting)return;beforeTone();
   const status={requested:'Short tone requested.',scheduled:'The short tone is scheduled.',stopped:'Sound stopped.',ended:'The scheduled tone ended.',unavailable:'Sound is unavailable here. You can still compare all the pictures.'};
   void (player??=createSoundWindowPlayer()).play(soundTonePlan(setting),{onStatus:event=>{if(!live())return;v.status=status[event.status]||'';root.querySelector('[data-sound-status]').textContent=v.status;}});return;
  }
  stopSound();stopSpeech();for(const d of root.querySelectorAll('[data-sound-details]'))v.details[d.dataset.soundDetails]=d.open;
  if(a==='stop'){v.status='Sound stopped.';root.querySelector('[data-sound-status]').textContent=v.status;return;}
  if(a==='watch'){v.film=true;redraw('return');return;}if(a==='return'){v.film=false;stopSoundFilm();redraw('watch');return;}
  const next=changeSoundWindow(v.model,['low','high'].includes(a)?'pitch':a.startsWith('size')?'size':['earlier','later'].includes(a)?'tick':a,['low','high'].includes(a)?a:a.startsWith('size')?Number(a.slice(4)):a==='earlier'?-1:a==='later'?1:a==='marker'?!v.model.marker:undefined);
  if(!next)return;v.model=next;v.status='';redraw(a==='earlier'&&next.tick===0?'later':a==='later'&&next.tick===32?'earlier':a==='clear'?'hold':a);
 }));
 root.addEventListener('click',e=>{if(e.target.closest?.('[data-speak]')&&!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});
 if(v.film){bindSoundMovie(root,()=>live()&&v.film,beforeMovie);root.addEventListener('keydown',e=>{if(e.key==='Escape'&&live()){e.preventDefault();v.film=false;stopSoundFilm();redraw('watch');}});}
}
function bindSoundMovie(root,live,beforePlay){
 stopSoundFilm();const video=root.querySelector('video'),play=root.querySelector('[data-sound-action=play]'),replay=root.querySelector('[data-sound-action=replay]'),retry=root.querySelector('[data-sound-action=retry]'),status=root.querySelector('[data-sound-load-status]'),caption=root.querySelector('[data-sound-caption]');
 let disposed=false,revision=0,playRevision=0,wanted=false,controller=null,source=null,track=null,playTask=null;const off=[];
 const on=(target,event,fn)=>{target.addEventListener(event,fn);off.push(()=>target.removeEventListener(event,fn));};
 const current=()=>!disposed&&live(),active=()=>current()&&!document.hidden;
 const pause=()=>{wanted=false;playRevision++;video.pause();if(current())play.textContent='Play';};soundFilmPause=pause;
 const detach=()=>{video.removeAttribute('src');track?.remove();track=null;video.load();if(source){URL.revokeObjectURL(source);source=null;}};
 const failure=()=>{if(current())status.textContent='The film could not play here. Read the transcript or return to the pictures.';};
 const updateCaption=()=>{if(current())caption.textContent=(video.ended?soundCaptions.at(-1):soundCaptions.find(c=>video.currentTime>=c.start&&video.currentTime<c.end))?.text||'\u00a0';};
 const requestPlay=()=>{if(!active()||!source)return;wanted=true;const serial=++playRevision,task={serial,revision};playTask=task;try{Promise.resolve(video.play()).then(()=>{if(playTask!==task)return;playTask=null;if(!active()||!wanted||serial!==playRevision||task.revision!==revision)video.pause();}).catch(e=>{if(playTask===task)playTask=null;if(e?.name!=='AbortError'&&current()&&serial===playRevision&&task.revision===revision){wanted=false;failure();}});}catch{playTask=null;wanted=false;failure();}};
 const load=async auto=>{
  if(!current())return;pause();controller?.abort();const rev=++revision;detach();controller=new AbortController();const signal=controller.signal;play.disabled=true;replay.disabled=true;status.textContent='Loading the vibration film…';wanted=auto&&!matchMedia('(prefers-reduced-motion: reduce)').matches;const ticket=playRevision;
  try{const response=await fetch('./assets/sound-wave-corrected.mp4',{signal});if(!response.ok)throw Error('Unavailable');const blob=await response.blob();if(!current()||rev!==revision)return;
   source=URL.createObjectURL(new Blob([blob],{type:'video/mp4'}));video.muted=true;video.src=source;track=document.createElement('track');track.kind='captions';track.srclang='en';track.label='English';track.src='./assets/sound-wave-corrected.vtt';video.append(track);track.track.mode='hidden';play.disabled=false;replay.disabled=false;status.textContent='';if(wanted&&ticket===playRevision&&active())requestPlay();
  }catch(e){if(current()&&rev===revision){wanted=false;status.textContent='';if(e?.name!=='AbortError')failure();}}
 };
 on(play,'click',()=>{if(!active()||play.disabled)return;if(video.paused)requestPlay();else pause();});on(replay,'click',()=>{if(!active()||replay.disabled)return;video.currentTime=0;requestPlay();});on(retry,'click',()=>{if(current())void load(false);});
 on(video,'play',()=>{if(!active()||(playTask&&(!wanted||playTask.serial!==playRevision||playTask.revision!==revision))){pause();return;}wanted=true;beforePlay();play.textContent='Pause';});on(video,'pause',()=>{wanted=false;playRevision++;if(current())play.textContent='Play';});on(video,'ended',()=>{wanted=false;updateCaption();});on(video,'timeupdate',updateCaption);on(video,'seeked',updateCaption);on(video,'error',failure);
 on(root.querySelector('[data-sound-transcript]'),'toggle',e=>{if(e.target.open&&current())pause();});on(document,'visibilitychange',()=>{if(document.hidden)pause();});on(window,'pagehide',pause);
 soundFilmCleanup=()=>{disposed=true;wanted=false;revision++;playRevision++;controller?.abort();off.forEach(fn=>fn());video.pause();detach();};void load(true);
}
